contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0));

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();
        address beforeOwner = c.owner();

        bool reverted;
        if (caller == beforeOwner) {
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        } else {
            (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            reverted = !success;
        }

        assert(caller == beforeOwner ? (!reverted && address(c).balance == 0 && c.depositsCount() == beforeCount && c.owner() == beforeOwner) : (reverted && address(c).balance == beforeBalance && c.depositsCount() == beforeCount && c.owner() == beforeOwner));
    }

    receive() external payable {}
}

