contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint value) public payable {
        require(address(c) != address(0), "invalid test setup");

        // Precondition: we are not the owner of c.
        require(msg.sender != c.owner(), "run must be called from a non-owner address");

        // Send some Ether to c so that c has a balance; the value is a parameter.
        uint sendAmount = value;
        require(address(this).balance >= sendAmount, "not enough balance to fund c");
        (bool sent, ) = address(c).call{value: sendAmount}("");
        require(sent, "funding c failed");

        // The withdraw call from a non-owner must revert.
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: for a non-owner caller, withdraw(value) reverts, and
        // the contract never paid out (its balance is exactly what we sent).
        assert(reverted && address(c).balance == sendAmount);
    }
}

