contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint _value) public payable {
        uint balBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(c).balance == balBefore - _value);
            assert(address(this).balance == selfBefore + _value);
        } else {
            assert(_value > balBefore);
            assert(address(c).balance == balBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint _value) public payable {
        uint balBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool success = !reverted;
        bool enough = _value <= balBefore;

        assert(
            (success == enough) &&
            (enough ? (address(c).balance == balBefore - _value && address(this).balance == selfBefore + _value)
                    : (address(c).balance == balBefore && address(this).balance == selfBefore))
        );
    }
}

